/// <summary>
/// This is an extension class for PurchLineOpenOrder form InventDim datasource.
/// </summary>
[ExtensionOf(FormDataSourcestr(PurchLineOpenOrder, InventDim))]
final class METPurchLineOpenOrderInventDimDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Filters the purchase order based on site id and warehouse.
    /// </summary>
    public void executeQuery()
    {
        FormDataSource inventDimDataSource = this as FormDataSource;
        FormRun formRun = inventDimDataSource.formRun();

        if (formRun.args().menuItemName() == menuItemDisplayStr(METPurchTableListPage))
        {
            METVendorChangeRequest vendorChangeRequest = formRun.args().record();
            QueryBuildDataSource inventDimQueryRunQbds = inventDimDataSource.queryBuildDataSource();
            inventDimQueryRunQbds.addRange(fieldNum(InventDim, InventSiteId)).value(vendorChangeRequest.SiteId);
            inventDimQueryRunQbds.addRange(fieldNum(InventDim, InventLocationId)).value(vendorChangeRequest.InventLocationId);
        }

        next executeQuery();
    }
